-- Source: supabase/access.sql and supabase/demo-projects.sql.
-- UTC instants remain text, including imported fractional-second precision.
-- UUIDs are generated by the application so imported IDs are never rewritten.
CREATE TABLE _ownership (
  project TEXT PRIMARY KEY NOT NULL,
  feature TEXT NOT NULL
);
INSERT INTO _ownership VALUES ('vibies', 'issue-5-access');

CREATE TABLE community (
  singleton INTEGER PRIMARY KEY NOT NULL DEFAULT 1 CHECK (singleton = 1),
  instructor_github_id TEXT,
  instructor_nickname TEXT,
  instructor_nickname_key TEXT,
  CHECK ((instructor_github_id IS NULL) = (instructor_nickname IS NULL)),
  CHECK ((instructor_nickname IS NULL) = (instructor_nickname_key IS NULL))
);
INSERT INTO community (singleton) VALUES (1);

CREATE TABLE accounts (
  internal_id TEXT NOT NULL UNIQUE,
  github_id TEXT PRIMARY KEY NOT NULL,
  github_username TEXT NOT NULL,
  nickname TEXT,
  nickname_key TEXT UNIQUE,
  status TEXT NOT NULL DEFAULT 'unapproved' CHECK (status IN ('unapproved','approved','revoked')),
  onboarding_completed INTEGER NOT NULL DEFAULT 0 CHECK (onboarding_completed IN (0,1)),
  CHECK ((status = 'unapproved' AND nickname IS NULL) OR (status IN ('approved','revoked') AND nickname IS NOT NULL)),
  CHECK ((nickname IS NULL) = (nickname_key IS NULL))
);

-- Sessions deliberately have no account FK: the Instructor is not an account row.
CREATE TABLE sessions (
  session_hash TEXT PRIMARY KEY NOT NULL,
  github_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  auth_provider TEXT NOT NULL DEFAULT 'legacy' CHECK (auth_provider IN ('legacy','github','google'))
);
CREATE INDEX sessions_created_at_idx ON sessions(created_at);
CREATE INDEX sessions_github_id_idx ON sessions(github_id);
CREATE TABLE sign_in_flows (
  state_hash TEXT PRIMARY KEY NOT NULL,
  browser_hash TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX sign_in_flows_created_at_idx ON sign_in_flows(created_at);
CREATE TABLE sign_in_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  browser_hash TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX sign_in_attempts_browser_created_idx ON sign_in_attempts(browser_hash,created_at);
CREATE TABLE instructor_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  previous_github_id TEXT,
  new_github_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE personal_projects (
  id TEXT PRIMARY KEY NOT NULL,
  owner_account_id TEXT NOT NULL REFERENCES accounts(internal_id),
  repository_id TEXT NOT NULL UNIQUE CHECK (length(repository_id) BETWEEN 1 AND 16 AND substr(repository_id,1,1) BETWEEN '1' AND '9' AND repository_id NOT GLOB '*[^0-9]*'),
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 80 AND title = trim(title)),
  summary TEXT NOT NULL CHECK (length(summary) BETWEEN 1 AND 500 AND summary = trim(summary)),
  demo_url TEXT CHECK (demo_url IS NULL OR (length(demo_url) BETWEEN 1 AND 2048 AND lower(substr(demo_url,1,8)) = 'https://' AND length(demo_url) > 8)),
  publication TEXT NOT NULL DEFAULT 'Draft' CHECK (publication IN ('Draft','Published','Archived')),
  connection TEXT NOT NULL DEFAULT 'Connected' CHECK (connection IN ('Connected','Disconnected')),
  moderation TEXT NOT NULL DEFAULT 'Visible' CHECK (moderation IN ('Visible','Hidden')),
  last_checked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0)
);
CREATE INDEX personal_projects_owner_idx ON personal_projects(owner_account_id);
CREATE TABLE project_milestones (
  id TEXT PRIMARY KEY NOT NULL,
  project_id TEXT NOT NULL REFERENCES personal_projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 80 AND title = trim(title)),
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0,1)),
  blocked_note TEXT CHECK (blocked_note IS NULL OR (length(blocked_note) BETWEEN 1 AND 500 AND blocked_note = trim(blocked_note))),
  position INTEGER NOT NULL CHECK (position BETWEEN 1 AND 20),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (completed = 0 OR blocked_note IS NULL),
  UNIQUE(project_id,position)
);
CREATE TABLE demo_projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
-- This public synthetic seed is replaced by source rows during reconciliation.
INSERT INTO demo_projects(id,title,summary) VALUES (1,'Vibies','A fictional community where beginners build and share small projects.');

-- These constraints serialize capacity decisions even under competing writers.
CREATE TRIGGER accounts_capacity_insert BEFORE INSERT ON accounts
WHEN NEW.status = 'approved' AND (SELECT count(*) FROM accounts WHERE status = 'approved') >= 8
BEGIN SELECT RAISE(ABORT,'member_capacity'); END;
CREATE TRIGGER accounts_capacity_update BEFORE UPDATE OF status ON accounts
WHEN NEW.status = 'approved' AND OLD.status <> 'approved' AND (SELECT count(*) FROM accounts WHERE status = 'approved') >= 8
BEGIN SELECT RAISE(ABORT,'member_capacity'); END;
CREATE TRIGGER accounts_nickname_insert BEFORE INSERT ON accounts
WHEN NEW.nickname_key = (SELECT instructor_nickname_key FROM community WHERE singleton = 1)
BEGIN SELECT RAISE(ABORT,'nickname_reserved'); END;
CREATE TRIGGER accounts_nickname_update BEFORE UPDATE OF nickname_key ON accounts
WHEN NEW.nickname_key = (SELECT instructor_nickname_key FROM community WHERE singleton = 1)
BEGIN SELECT RAISE(ABORT,'nickname_reserved'); END;
CREATE TRIGGER community_nickname_update BEFORE UPDATE OF instructor_nickname_key ON community
WHEN EXISTS (SELECT 1 FROM accounts WHERE nickname_key = NEW.instructor_nickname_key)
BEGIN SELECT RAISE(ABORT,'nickname_reserved'); END;
CREATE TRIGGER projects_capacity_insert BEFORE INSERT ON personal_projects
WHEN (SELECT count(*) FROM personal_projects WHERE owner_account_id = NEW.owner_account_id) >= 3
BEGIN SELECT RAISE(ABORT,'project_capacity'); END;
CREATE TRIGGER projects_capacity_update BEFORE UPDATE OF owner_account_id ON personal_projects
WHEN NEW.owner_account_id <> OLD.owner_account_id AND (SELECT count(*) FROM personal_projects WHERE owner_account_id = NEW.owner_account_id) >= 3
BEGIN SELECT RAISE(ABORT,'project_capacity'); END;
